package com.acme.hospital.clinical;

import java.time.LocalDateTime;

/**
 * Guards against writing observations to patients who are no longer admitted.
 */
public class ObservationWriteGuard {

    private final PatientRepository patients;

    public ObservationWriteGuard(PatientRepository patients) {
        this.patients = patients;
    }

    public void assertAdmitted(String patientId) {
        Patient patient = patients.require(patientId);
        if (patient.getDischargedAt() != null) {
            throw new PatientDischargedException(
                "Patient " + patientId + " was discharged at " + patient.getDischargedAt());
        }
        if (patient.getAdmittedAt() == null) {
            throw new PatientNotAdmittedException(patientId);
        }
    }

    public boolean isWritable(String patientId) {
        Patient p = patients.find(patientId);
        return p != null && p.getAdmittedAt() != null && p.getDischargedAt() == null;
    }
}

class PatientDischargedException extends RuntimeException {
    public PatientDischargedException(String message) { super(message); }
}

class PatientNotAdmittedException extends RuntimeException {
    public PatientNotAdmittedException(String id) { super("Not admitted: " + id); }
}

