package com.acme.hospital.vitals;

import java.util.Optional;

/**
 * Derives BMI and a coarse category from the latest height and weight measurements.
 */
public class BmiCalculator {

    private final VitalSignsRepository vitals;

    public BmiCalculator(VitalSignsRepository vitals) {
        this.vitals = vitals;
    }

    public Optional<BmiResult> forPatient(String patientId) {
        Optional<Double> heightM = vitals.latestValue(patientId, VitalKind.HEIGHT_M);
        Optional<Double> weightKg = vitals.latestValue(patientId, VitalKind.WEIGHT_KG);
        if (heightM.isEmpty() || weightKg.isEmpty() || heightM.get() <= 0) {
            return Optional.empty();
        }
        double bmi = weightKg.get() / (heightM.get() * heightM.get());
        return Optional.of(new BmiResult(bmi, categorise(bmi)));
    }

    private BmiCategory categorise(double bmi) {
        if (bmi < 18.5) return BmiCategory.UNDERWEIGHT;
        if (bmi < 25.0) return BmiCategory.NORMAL;
        if (bmi < 30.0) return BmiCategory.OVERWEIGHT;
        return BmiCategory.OBESE;
    }
}

