package com.acme.hospital.discharge;

import java.time.LocalDateTime;

/**
 * Discharge workflow: verifies no active meds remain, closes the admission, releases bed.
 */
public class DischargeWorkflow {

    private final PatientRepository patients;
    private final MedicationRepository medications;
    private final BedAllocationService beds;

    public DischargeWorkflow(PatientRepository patients,
                             MedicationRepository medications,
                             BedAllocationService beds) {
        this.patients = patients;
        this.medications = medications;
        this.beds = beds;
    }

    public void discharge(String patientId) {
        if (!medications.findActiveForPatient(patientId).isEmpty()) {
            throw new ActivePrescriptionsRemainException(patientId);
        }
        Patient p = patients.require(patientId);
        p.setDischargedAt(LocalDateTime.now());
        patients.save(p);
        beds.releaseForPatient(patientId);
    }
}

class ActivePrescriptionsRemainException extends RuntimeException {
    public ActivePrescriptionsRemainException(String id) {
        super("Active prescriptions remain for " + id);
    }
}

