package com.acme.hospital.vitals;

import java.time.Instant;
import java.util.List;

/**
 * Provides a chronological series of vital sign readings for the last 24h.
 */
public class VitalsTrendService {

    private final VitalSignsRepository vitals;

    public VitalsTrendService(VitalSignsRepository vitals) {
        this.vitals = vitals;
    }

    public List<VitalReading> last24Hours(String patientId, VitalKind kind) {
        Instant since = Instant.now().minusSeconds(24 * 3600);
        return vitals.findBetween(patientId, kind, since, Instant.now());
    }

    public TrendSummary summarise(String patientId, VitalKind kind) {
        List<VitalReading> series = last24Hours(patientId, kind);
        if (series.isEmpty()) {
            return TrendSummary.empty(kind);
        }
        double min = series.stream().mapToDouble(VitalReading::getValue).min().orElseThrow();
        double max = series.stream().mapToDouble(VitalReading::getValue).max().orElseThrow();
        double last = series.get(series.size() - 1).getValue();
        return new TrendSummary(kind, min, max, last);
    }
}

