package com.acme.hospital.audit;

import java.time.Instant;
import javax.persistence.EntityManager;
import javax.persistence.EntityTransaction;

/**
 * Writes an access entry to the patient-record audit table on each read.
 */
public class RecordAccessAuditor {

    private final EntityManager em;

    public RecordAccessAuditor(EntityManager em) {
        this.em = em;
    }

    public void logRead(String userId, String patientId, String purpose) {
        EntityTransaction tx = em.getTransaction();
        tx.begin();
        try {
            AccessAuditEntry entry = new AccessAuditEntry();
            entry.setUserId(userId);
            entry.setPatientId(patientId);
            entry.setPurpose(purpose);
            entry.setOccurredAt(Instant.now());
            em.persist(entry);
            tx.commit();
        } catch (RuntimeException ex) {
            tx.rollback();
            throw ex;
        }
    }
}

