/**
 * Decides whether the current user may view a patient's full clinical record.
 */
public class RecordAccessPolicy {

    private final PatientRepository patients;
    private final StaffDirectory staff;

    public RecordAccessPolicy(PatientRepository patients, StaffDirectory staff) {
        this.patients = patients;
        this.staff = staff;
    }

    public void assertCanView(String userId, String patientId) {
        Patient p = patients.require(patientId);
        String ward = p.getCurrentWard();
        if (ward == null || !staff.isAssignedToWard(userId, ward)) {
            throw new AccessDeniedException(
                "User " + userId + " not assigned to ward " + ward);
        }
    }

    public boolean canView(String userId, String patientId) {
        try {
            assertCanView(userId, patientId);
            return true;
        } catch (AccessDeniedException e) {
            return false;
        }
    }
}

