/* admission_bed.c - allocate next free bed in a ward, or fail if none available */
#include <stdio.h>
#include <string.h>
#include "hospital_db.h"

int allocate_bed(const char *patient_id, const char *ward_id,
                 char *out_bed_code, size_t out_len) {
    bed_cursor_t *cur = NULL;
    if (db_open_free_bed_cursor(&cur, ward_id) != DB_OK) {
        return -1;
    }

    bed_row_t row;
    int allocated = 0;
    while (db_bed_cursor_next(cur, &row) == DB_OK) {
        snprintf(out_bed_code, out_len, "%s", row.bed_code);
        allocated = 1;
        break; /* cursor is ordered by bed_code ascending */
    }
    db_close_cursor(cur);

    if (!allocated) {
        fprintf(stderr, "ward %s has no free bed\n", ward_id);
        return -2;
    }

    char now[32];
    db_current_timestamp(now, sizeof(now));
    return db_insert_bed_allocation(patient_id, ward_id, out_bed_code, now);
}

